   "schema": {
    "type": "object",
    "properties": {
     "prompt": {
      "type": "string",
      "description": "What to ask the user to do, in one line. Shown on the window, e.g. 'Sign in to Naukri so I can apply for you'."
     },
     "check": {
      "type": "boolean",
      "description": "True to poll an existing handoff instead of starting one."
     },
     "session": {
      "type": "string",
      "description": "\"scratch\" (default) or \"mine\" (signed-in browser)."
     },
     "max_text_chars": {
      "type": "number",
      "description": "Page-text cap (default 4000)."
     },
     "max_elements": {
      "type": "number",
      "description": "Element cap (default 60)."
     }
    },
    "required": []
   }
